cases.setup:
git init -q . && printf 'module calc

go 1.22
' > go.mod && printf 'package calc

func Clamp(v, lo, hi int) int {
	if v < lo {
		return lo
	}
	if v > hi {
		return hi
	}
	return v
}
' > clamp.go && git add . && git -c user.email=e@e -c user.name=eval commit -qm 'feat: clamp'

assert.value:
cp clamp.go c.bak && printf 'package calc

func Clamp(v, lo, hi int) int {
	return v
}
' > clamp.go; go test ./... >/dev/null 2>&1; rc=$?; cp c.bak clamp.go; rm -f c.bak; [ $rc -ne 0 ]
